g=[[7]*29 for _ in range(23)]
pts={ (9,2):6,(10,3):6,(9,5):2,(10,4):2,(11,3):0,(12,2):0,(11,4):8}
for (r,c),v in pts.items(): g[r][c]=v
# extend lines in both directions along pair vector
for color, p1,p2 in [(6,(9,2),(10,3)),(2,(9,5),(10,4)),(0,(11,3),(12,2))]:
 dr=p2[0]-p1[0]; dc=p2[1]-p1[1]
 for start,sign in [(p1,-1),(p2,1)]:
  r,c=start
  while 0<=r<23 and 0<=c<29:
   if g[r][c]==7: g[r][c]=color
   r+=sign*dr;c+=sign*dc
print(g)
